#
# t_phase2_utilities.jl
#
# Point-wise comparison of the P2 functions with NESSi: utilities, GF
# algebra, differentiation, incremental / partial lesser / equal-time
# convolutions, and response convolution.
#
# The data are generated by .nessi/kbref/p2_*.cpp. The closed-form inputs
# of .nessi/kbref/p2_common.hpp are rebuilt here with exactly the same
# formulas (nothing is read back from the output). The order and alpha of
# every case are read from the labels files, never guessed from the file
# names.
#
# Index translation: NESSi tstp = -1, 0, ..., nt <-> KB tstp = 0, 1, ...,
# nt + 1 (see common.jl).
#

using LinearAlgebra

const P2_NT = 12
const P2_NTAU = 24
const P2_BETA = 2.0
const P2_H = 0.05
const P2_MU = 0.1
const P2_DATA = joinpath(@__DIR__, "data")

p2_hamiltonian(which) = which == 0 ? C64[-0.5 0.2+0.1im; 0.2-0.1im 0.4] :
                                     C64[0.3 0.25-0.05im; 0.25+0.05im -0.2]
p2_phase(which, t) = which == 0 ? 0.3 * (1.0 - cos(t)) : 0.1 * (1.0 - cos(2.0 * t))
p2_middle(t) = C64[1.0+0.2t 0.1+0.3t*im; -0.2+0.05im 0.8]

p2_contour(size, ntau = P2_NTAU) =
    Cn(P2_NT + 1, ntau + 1, size, size, P2_NT * P2_H, P2_BETA)

#
# Free Green's function, see p2_common.hpp
#
function p2_green(which, size, sig; ntau = P2_NTAU)
    C = p2_contour(size, ntau)
    G = ℱ(C, sig)
    shift = sig == BOSE ? 1.5 : 0.0
    ϵ = p2_hamiltonian(which)[1:size,1:size] + (shift - P2_MU) * I
    e, V = eigen(Hermitian(ϵ))
    fd(g) = V * diagm(C64.(g)) * V'
    n = 1.0 ./ (exp.(P2_BETA .* e) .- sig)
    for q = 0:ntau
        τ = q * P2_BETA / ntau
        G.mat[q+1] = fd(-exp.(-e .* τ) .* (1.0 .+ sig .* n))
    end
    U = [fd(exp.(-im .* e .* (i * P2_H))) * exp(-im * p2_phase(which, i * P2_H))
         for i = 0:P2_NT]
    ρ = fd(n)
    for i = 0:P2_NT
        for j = 0:i
            G.ret[i+1,j+1] = -im * U[i+1] * U[j+1]'
        end
        for j = i:P2_NT
            G.less[i+1,j+1] = (-im * sig) * U[i+1] * ρ * U[j+1]'
        end
        for q = 0:ntau
            τ = q * P2_BETA / ntau
            G.lmix[i+1,q+1] = (-im * sig) * U[i+1] * fd(n .* exp.(e .* τ))
        end
    end
    return C, G
end

function p2_function(C, size)
    f = Cf(C, zero(C64))
    f[0] = p2_middle(-0.5)[1:size,1:size]
    for i = 0:P2_NT
        f[i+1] = p2_middle(i * P2_H)[1:size,1:size]
    end
    return f
end

p2_read(name) = read_kbref(joinpath(P2_DATA, name * ".dat"))
p2_case(d::KbrefData) = parse(Int, d.metadata["case_id"])

#
# Compare a KB value with a reference value; returns the absolute error.
#
function p2_check(v, ref; what = "")
    ok = isapprox(v, ref; atol = 1e-10, rtol = 1e-10)
    ok || @error "kbref mismatch" what nessi_value = ref kb_value = v
    @test ok
    return abs(v - ref)
end

#
# Compare a herm_matrix file, return the overall maximal error.
#
p2_gf(G, ref) = maximum(values(test_kbref(G, ref; atol = 1e-10, rtol = 1e-10)))

@testset verbose = true "NESSi: phase 2 utilities" begin

    @testset "utilities and GF algebra" begin
        lab = p2_read("p2_utilities_labels")
        C, A = p2_green(0, 2, FERMI)
        _, B = p2_green(1, 2, FERMI)
        f = p2_function(C, 2)
        maxerr = 0.0
        #
        # Collect the cases and their labels
        gfnames = [
            ["p2_utilities_extrap_gf_k$k" for k = 1:5];
            ["p2_utilities_t0_fermi", "p2_utilities_t0_bose",
             "p2_utilities_tk_fermi", "p2_utilities_tk_bose",
             "p2_utilities_hermitian", "p2_utilities_submatrix",
             "p2_utilities_lmul_hermconj", "p2_utilities_rmul_hermconj"]]
        gfs = Dict(n => p2_read(n) for n in gfnames)
        fex = p2_read("p2_utilities_extrapolate")
        fin = p2_read("p2_utilities_interpolate")
        dst = p2_read("p2_utilities_distance")
        ord_cases = [[p2_case(gfs["p2_utilities_extrap_gf_k$k"]) for k = 1:5];
                     unique(r.i for r in fex.rows); unique(r.i for r in fin.rows)]
        all_cases = [ord_cases; [p2_case(gfs[n]) for n in gfnames[6:end]];
                     unique(r.i for r in dst.rows)]
        labels = labels_by_case(lab, all_cases; order = ord_cases, alpha = false)
        #
        # extrapolate_timestep! for ℱ
        for k = 1:5
            ref = gfs["p2_utilities_extrap_gf_k$k"]
            G = deepcopy(A)
            extrapolate_timestep!(P2_NT, G, labels[p2_case(ref)].order)
            maxerr = max(maxerr, p2_gf(G, ref))
        end
        #
        # extrapolate_timestep! for Cf
        for c in unique(r.i for r in fex.rows)
            g = deepcopy(f)
            extrapolate_timestep!(P2_NT, g, labels[c].order)
            for r in fex.rows
                r.i == c || continue
                maxerr = max(maxerr, p2_check(g[r.j+1][r.a+1,r.b+1], r.value;
                                              what = "extrapolate case $c"))
            end
        end
        #
        # interpolation
        tinter = parse(F64, fin.metadata["tinter"])
        tstp = parse(Int, fin.metadata["tstp"])
        for r in fin.rows
            x = interpolation(tstp + 1, tinter + 1, f, labels[r.i].order)
            maxerr = max(maxerr, p2_check(x[r.a+1,r.b+1], r.value;
                                          what = "interpolate case $(r.i)"))
        end
        #
        # distance
        offset = parse(Int, dst.metadata["case_id_offset"])
        for r in dst.rows
            t = r.i - offset + 1  # KB time step
            v = r.component == "distance_ret" ? distance(A, B, t, Val(:ret)) :
                r.component == "distance_tv" ? distance(A, B, t, Val(:tv)) :
                r.component == "distance_les" ? distance(A, B, t, Val(:les)) :
                distance(A, B, t)
            maxerr = max(maxerr, p2_check(complex(v), r.value;
                                          what = "$(r.component) tstp $(t-1)"))
        end
        #
        # from_mat! and from_mat!
        for (sig, tag) in ((FERMI, "fermi"), (BOSE, "bose"))
            Cs, G = p2_green(0, 2, sig)
            G0 = ℱ(Cs, sig)
            Gk = ℱ(Cs, sig)
            memcpy!(G, G0, 0)
            memcpy!(G, Gk, 0)
            from_mat!(G0)
            ref = gfs["p2_utilities_tk_$tag"]
            from_mat!(Gk, parse(Int, ref.metadata["kt"]))
            maxerr = max(maxerr, p2_gf(G0, gfs["p2_utilities_t0_$tag"]))
            maxerr = max(maxerr, p2_gf(Gk, ref))
        end
        #
        # force_matsubara_hermitian!
        G = deepcopy(A)
        for q = 1:P2_NTAU+1
            G.mat[q] = A.mat[q] + im * B.mat[q]
        end
        force_matsubara_hermitian!(G)
        maxerr = max(maxerr, p2_gf(G, gfs["p2_utilities_hermitian"]))
        #
        # elemcpy! with index maps (NESSi set_submatrix)
        G = ℱ(C, FERMI)
        elemcpy!([2, 2, 1, 1], [2, 1, 2, 1], A, [1, 1, 2, 2], [1, 2, 1, 2], G)
        maxerr = max(maxerr, p2_gf(G, gfs["p2_utilities_submatrix"]))
        #
        # smul! with Val(:adjoint)
        w = parse(F64, gfs["p2_utilities_lmul_hermconj"].metadata["weight"])
        L = deepcopy(A)
        R = deepcopy(A)
        for t = 0:P2_NT+1
            smul!(f, L, t, Val(:adjoint), w)
            smul!(R, f, t, Val(:adjoint), w)
        end
        maxerr = max(maxerr, p2_gf(L, gfs["p2_utilities_lmul_hermconj"]))
        maxerr = max(maxerr, p2_gf(R, gfs["p2_utilities_rmul_hermconj"]))
        #
        @printf("  %-40s max err: %.2e\n", "p2_utilities", maxerr)
        @test maxerr ≤ 1e-10
    end

    @testset "differentiation" begin
        lab = p2_read("p2_differentiation_labels")
        refs = Dict{String,KbrefData}()
        for k = 1:5, tag in ("fermi", "bose", "min"), d in (1, 2)
            n = "p2_differentiation_$(tag)_k$(k)_d$(d)"
            refs[n] = p2_read(n)
        end
        cases = [p2_case(r) for r in values(refs)]
        labels = labels_by_case(lab, cases; order = true, alpha = false)
        maxerr = 0.0
        for k = 1:5, tag in ("fermi", "bose", "min")
            sig = tag == "bose" ? BOSE : FERMI
            ntau = tag == "min" ? 2 * k + 1 : P2_NTAU
            # NESSi 2.0.0 differentiation supports size1 = 1 only (it uses
            # scalar element accessors), see p2_differentiation.cpp.
            C, A = p2_green(0, 1, sig; ntau = ntau)
            for d in (1, 2)
                ref = refs["p2_differentiation_$(tag)_k$(k)_d$(d)"]
                kk = labels[p2_case(ref)].order
                @test kk == k
                @test parse(Int, ref.metadata["ntau"]) == ntau
                dA = ℱ(C, sig)
                for t = 0:P2_NT+1
                    if d == 1
                        deriv1_timestep!(t, dA, A, A, P2_BETA, P2_H, kk)
                    else
                        deriv2_timestep!(t, dA, A, A, P2_BETA, P2_H, kk)
                    end
                end
                maxerr = max(maxerr, p2_gf(dA, ref))
            end
        end
        @printf("  %-40s max err: %.2e\n", "p2_differentiation", maxerr)
        @test maxerr ≤ 1e-10
    end

    @testset "convolution utilities" begin
        lab = p2_read("p2_convolution_utilities_labels")
        pre = "p2_convolution_utilities"
        parts = ("incr", "incr_ret_less", "incr_less_adv", "incr_lmix_rmix", "incr_les")
        #
        # Read all files and join the labels
        gfs = Dict{String,KbrefData}()
        elems = Dict{String,KbrefData}()
        for tag in ("fermi", "bose"), k in (1, 5)
            for fm in ("nof", "f")
                for p in parts
                    n = "$(pre)_$(tag)_k$(k)_$(fm)_$(p)"
                    gfs[n] = p2_read(n)
                end
                n = "$(pre)_$(tag)_k$(k)_$(fm)_startup"
                elems[n] = p2_read(n)
            end
            n = "$(pre)_$(tag)_k$(k)_eq"
            elems[n] = p2_read(n)
        end
        alpha_cases = Int[p2_case(r) for r in values(gfs)]
        eq_cases = Int[]
        for (n, d) in elems
            ids = unique(r.i for r in d.rows)
            endswith(n, "_eq") ? append!(eq_cases, ids) : append!(alpha_cases, ids)
        end
        labels = labels_by_case(lab, [alpha_cases; eq_cases];
                                order = true, alpha = alpha_cases)
        #
        maxerr = 0.0
        for (sig, tag) in ((FERMI, "fermi"), (BOSE, "bose")), k in (1, 5)
            C, A = p2_green(0, 2, sig)
            _, B = p2_green(1, 2, sig)
            f = p2_function(C, 2)
            for (fx, fm) in ((nothing, "nof"), (f, "f"))
                # Full incremental convolution, C₀ = A
                ref = gfs["$(pre)_$(tag)_k$(k)_$(fm)_incr"]
                lb = labels[p2_case(ref)]
                @test lb.order == k
                I = Integrator(lb.order)
                X = deepcopy(A)
                for t = 0:P2_NT+1
                    incr_convolution!(t, X, A, A, fx, B, B, I, P2_BETA, P2_H, lb.alpha)
                end
                maxerr = max(maxerr, p2_gf(X, ref))
                #
                # Partial lesser convolutions and the lesser increment
                pfuns = (incr_convolution_ret_less!, incr_convolution_less_adv!,
                         incr_convolution_lmix_rmix!, incr_convolution_les!)
                Ys = ℱ[]
                for (p, pf) in zip(parts[2:end], pfuns)
                    ref = gfs["$(pre)_$(tag)_k$(k)_$(fm)_$(p)"]
                    lb = labels[p2_case(ref)]
                    Y = ℱ(C, sig)
                    for t = 1:P2_NT+1
                        pf(t, Y, A, A, fx, B, B, Integrator(lb.order), P2_BETA, P2_H, lb.alpha)
                    end
                    maxerr = max(maxerr, p2_gf(Y, ref))
                    push!(Ys, Y)
                end
                # The lesser increment is the sum of the three partials
                S = deepcopy(Ys[1])
                incr!(S, Ys[2], 1.0)
                incr!(S, Ys[3], 1.0)
                for t = 1:P2_NT+1
                    @test distance(S, Ys[4], t, Val(:les)) ≤ 1e-12
                end
                #
                # Start-up source blocks (private scratch-target buffers),
                # NESSi n = 0, ..., k - 1 <-> KB tstp = 1, ..., k.
                ref = elems["$(pre)_$(tag)_k$(k)_$(fm)_startup"]
                ws = KadanoffBaym._ConvWorkspace(A, B)
                for comp in ("startup_less_adv", "startup_lmix_rmix")
                    for c in unique(r.i for r in ref.rows if r.component == comp)
                        lb = labels[c]
                        I = Integrator(lb.order)
                        rows = [r for r in ref.rows if r.i == c && r.component == comp]
                        n = c - parse(Int, ref.metadata[comp == "startup_less_adv" ?
                                    "less_adv_case_id_offset" : "lmix_rmix_case_id_offset"])
                        buf = [zeros(C64, 2, 2) for _ = 1:max(n, k)+1]
                        if comp == "startup_less_adv"
                            KadanoffBaym._incr_convolution_less_adv!(buf, n + 1, A, A, fx,
                                B, B, I, P2_BETA, P2_H, lb.alpha, ws)
                        else
                            KadanoffBaym._incr_convolution_lmix_rmix!(buf, n + 1, A, A, fx,
                                B, B, I, P2_BETA, P2_H, lb.alpha, ws)
                        end
                        @test length(rows) == 4 * (k + 1)
                        for r in rows
                            maxerr = max(maxerr, p2_check(buf[r.j+1][r.a+1,r.b+1], r.value;
                                                          what = "$comp case $c j $(r.j)"))
                        end
                    end
                end
            end
            #
            # Equal-time convolutions
            ref = elems["$(pre)_$(tag)_k$(k)_eq"]
            f = p2_function(C, 2)
            for r in ref.rows
                I = Integrator(labels[r.i].order)
                t = r.j + 1
                x = if r.component == "les_timediag"
                    convolution_les_timediag(t, A, B, I, P2_BETA, P2_H)
                elseif r.i % 100 == 61
                    convolution_density_matrix(t, A, A, nothing, B, B, I, P2_BETA, P2_H)
                else
                    convolution_density_matrix(t, A, A, f, B, B, I, P2_BETA, P2_H)
                end
                maxerr = max(maxerr, p2_check(x[r.a+1,r.b+1], r.value;
                                              what = "$(r.component) case $(r.i) tstp $(r.j)"))
            end
        end
        @printf("  %-40s max err: %.2e\n", "p2_convolution_utilities", maxerr)
        @test maxerr ≤ 1e-10
    end

    @testset "response convolution" begin
        ref = p2_read("p2_response_values")
        lab = p2_read("p2_response_labels")
        labels = labels_by_case(lab, unique(r.i for r in ref.rows);
                                order = true, alpha = false)
        orbs = ((0, 0, 0, 0), (0, 1, 1, 0), (1, 0, 0, 1), (1, 1, 1, 1))
        Ws = Dict(s => p2_green(0, s, FERMI) for s in (1, 2))
        maxerr = 0.0
        for r in ref.rows
            c = r.i
            tstp = c % 16 - 1
            orb = (c ÷ 16) % 4
            k = (c ÷ 64) % 5 + 1
            size = c ÷ 320 + 1
            @test labels[c].order == k
            C, W = Ws[size]
            f = p2_function(C, size)
            a1, a2, b1, b2 = orbs[orb+1] .+ 1
            v = response_convolution(tstp + 1, W, a1, a2, f, b1, b2, k, P2_BETA, P2_H)
            maxerr = max(maxerr, p2_check(v, r.value; what = "response case $c"))
            # The 𝒻 version (outside of the start-up region)
            if tstp == -1 || tstp ≥ k
                v = response_convolution(tstp + 1, W[tstp+1], a1, a2, f, b1, b2, k,
                                         P2_BETA, P2_H)
                maxerr = max(maxerr, p2_check(v, r.value; what = "response 𝒻 case $c"))
            end
        end
        @printf("  %-40s max err: %.2e\n", "p2_response", maxerr)
        @test maxerr ≤ 1e-10
    end
end
